WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.OwnerUserId, p.Score, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserStats AS (SELECT u.Id AS UserId, u.Reputation, COUNT(DISTINCT p.Id) AS TotalPosts, SUM(COALESCE(v.BountyAmount, 0)) AS TotalBounties FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId LEFT JOIN Votes AS v ON p.Id = v.PostId AND v.VoteTypeId = 8 GROUP BY u.Id, u.Reputation), PostLinksCounts AS (SELECT pl.PostId, COUNT(pl.RelatedPostId) AS LinkCount FROM PostLinks AS pl GROUP BY pl.PostId), RecentCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId) SELECT rp.Title, ps.UserId, ps.Reputation, ps.TotalPosts, ps.TotalBounties, pl.LinkCount, rc.CloseReasons FROM RankedPosts AS rp JOIN UserStats AS ps ON rp.OwnerUserId = ps.UserId LEFT JOIN PostLinksCounts AS pl ON rp.PostId = pl.PostId LEFT JOIN RecentCloseReasons AS rc ON rp.PostId = rc.PostId WHERE rp.PostRank = 1 ORDER BY ps.Reputation DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST LIMIT 10